CREATE TABLE IF NOT EXISTS reschedule_request_slots (request_id BIGINT UNSIGNED NOT NULL, slot_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY (request_id, slot_id), UNIQUE (slot_id), CONSTRAINT fk_reschedule_hold_request FOREIGN KEY (request_id) REFERENCES reschedule_requests(id) ON DELETE CASCADE, CONSTRAINT fk_reschedule_hold_slot FOREIGN KEY (slot_id) REFERENCES professional_slots(id) ON DELETE CASCADE);
